package mz.co.aprendaacodar.audit.entity;
import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.user.entity.User;import java.util.Map;import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY) private User actor;@Column(nullable=false,length=100) private String action;@Column(nullable=false,length=100) private String entityType;@Column(nullable=false) private UUID entityId;@JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb") private Map<String,Object> details;protected AuditLog(){}public AuditLog(User actor,String action,String type,UUID id,Map<String,Object> details){this.actor=actor;this.action=action;entityType=type;entityId=id;this.details=details;}public String getAction(){return action;}public UUID getEntityId(){return entityId;}public Map<String,Object> getDetails(){return details;}}
